// Sealed dialog state to manage all dialogs from a single source of truth
sealed interface DialogState {
    data object ReportProblem : DialogState
    data object FirstTime : DialogState
    data class Permission(val permission: PermissionState) : DialogState

    // Keeps Block Apps dialog open, and optionally shows a nested confirm dialog for a selected app
    data class BlockApps(val confirmApp: AppInfo? = null) : DialogState
    data object HowItWorks : DialogState
    data object BlockWords : DialogState
    data class EnableProtectionConfirm(val level: DnsProtectionLevel) :
        DialogState
}


class AppActivity : ComponentActivity() {
    var dialogState by mutableStateOf<DialogState?>(if (MyApp.isFirstTime) DialogState.FirstTime else null)

    val backStack by lazy {
        mutableStateListOf(
            if (!isServiceRunning(this, MyAccessibilityService::class.java)) Screen.EnableProtection
            else Screen.ProtectionActivated
        )
    }
    private var overlayPermission by mutableStateOf(false)
    private var usageStatsPermission by mutableStateOf(false)
    private var accessibilityPermission by mutableStateOf(false)
    private var permissionState by mutableStateOf<PermissionState?>(null)
    private var notificationPermission by mutableStateOf(
        Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU
    )
    private val adminReceiver by lazy {
        ComponentName(
            this,
            AppDeviceAdminReceiver::class.java
        )
    }
    private val requestAdmin = registerForActivityResult(
        ActivityResultContracts.StartActivityForResult()
    )
    {
        // Handle result if needed
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        val splashscreen = installSplashScreen()
        var keepSplashScreen = true
        super.onCreate(savedInstanceState)
        setLayoutDirection(window.decorView, ViewCompat.LAYOUT_DIRECTION_RTL)
        splashscreen.setKeepOnScreenCondition { keepSplashScreen }
        lifecycleScope.launch {
            delay(3000)
            keepSplashScreen = false
        }
        val viewModel: AppViewModel = getViewModel()
        val sharedPrefs: SharedPrefs by inject(SharedPrefs::class.java)
        viewModel.loadInstalledApps(getAllApps())
        viewModel.loadBlockedWords()
        MyLog.i(TAG, "Opening app")
        //viewModel.handleUpdateStatus(this)
        refreshPermissionState()
        enableEdgeToEdge()
        requestAdminPermission(adminReceiver, requestAdmin)

        setContent {
            CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Rtl) {
                AinaaTheme {
                    MainRoot(
                        viewModel = viewModel,
                        sharedPrefs = sharedPrefs,
                    )
                }
            }
        }

    }

    @Composable
    private fun MainRoot(
        context: Context = LocalContext.current,
        viewModel: AppViewModel,
        sharedPrefs: SharedPrefs,
    ) {
        val snackbarHostState = remember { SnackbarHostState() }
        val apps = viewModel.apps.collectAsState().value

        val secretComboTracker = remember { mutableStateListOf<Char>() }
        val addComboClick: (Char) -> Unit = { c ->
            secretComboTracker.add(c)
            if (secretComboTracker.size > 6) {
                secretComboTracker.removeAt(0)
            }
            if (secretComboTracker.joinToString("") == "tttbbt") {
                System.exit(0)
            }
        }

        // Centralized dialogs rendering
        when (val d = dialogState) {
            is DialogState.ReportProblem -> {
                ReportProblemDialog(
                    onClose = { dialogState = null },
                    onSubmit = { report ->
                        viewModel.submitReport(report) {
                            when (it) {
                                NetworkResult.Success -> {
                                    Toast.makeText(
                                        context,
                                        context.getString(R.string.report_sent_message),
                                        Toast.LENGTH_LONG
                                    ).show()
                                }

                                is NetworkResult.Error -> {
                                    Toast.makeText(
                                        context,
                                        getString(R.string.report_send__faild_message, '$'),
                                        Toast.LENGTH_LONG
                                    ).show()
                                }

                                else -> {}
                            }
                        }
                        dialogState = null
                    }
                )
            }

            is DialogState.FirstTime -> {
                OkDialog(
                    title = stringResource(R.string.test_version_text),
                    message = stringResource(R.string.test_version_message).trimIndent(),
                    onDismiss = {
                        dialogState = null
                        MyApp.isFirstTime = false
                    }
                )
            }

            is DialogState.Permission -> {
                PermissionDialog(
                    permissionState = d.permission,
                    onDismiss = { dialogState = null },
                    onClick = {
                        grantPermission(d.permission)
                        dialogState = null
                    }
                )
            }

            is DialogState.BlockApps -> {
                BlockAppDialog(
                    onDismiss = { dialogState = null },
                    appStates = apps,
                    onBlockClick = { app ->
                        dialogState = BlockApps(confirmApp = app)
                    }
                )
                if (d.confirmApp != null) {
                    ConfirmBlockedDialog(
                        app = d.confirmApp,
                        onDismiss = { dialogState = BlockApps() },
                        onConfirm = {
                            viewModel.toggleAppSelection(it.packageName)
                            dialogState = BlockApps()
                        }
                    )
                }
            }

            is DialogState.HowItWorks -> {
                HowItWorksDialog(
                    onDismiss = { dialogState = null },
                    onContactClicked = { context.openUrl(SUPPORT_CONTACT_URL) },
                    onSafeSearchClicked = { context.openUrl(SAFE_SEARCH_URL) },
                    image = stringResource(R.string.howtoknow_asset).toUri()
                )
            }

            is DialogState.EnableProtectionConfirm -> {
                EnableProtectionDialog(
                    onConfirm = {
                        dialogState = null // Close the confirmation dialog
                        viewModel.saveLevel(d.level)
                        refreshPermissionState()
                        if (permissionState == null) {
                            // All permissions are already granted! Activate protection.
                            Toast.makeText(
                                context,
                                context.getString(R.string.protection_activated_text),
                                Toast.LENGTH_LONG
                            ).show()
                            startAccessibilityService(MyAccessibilityService.ACTION_START_FOREGROUND)
                            backStack.add(Screen.ProtectionActivated)
                            backStack.remove(Screen.EnableProtection)
                        } else {
                            dialogState = DialogState.Permission(permissionState!!)
                        }
                    },
                    onDismiss = { dialogState = null }
                )
            }

            DialogState.BlockWords -> {
                ManageKeywordsDialog(
                    keywords = viewModel.blockedWords.collectAsState().value.toSet(),
                    onDismiss = { dialogState = null },
                    onAddKeyword = { viewModel.addBlockedWord(it) },
                    onRemoveKeyword = { viewModel.removeBlockedWord(it) })
            }

            null -> {}
        }

        // Current Screen
        val currentScreen = backStack.lastOrNull()

        Scaffold(
            snackbarHost = { SnackbarHost(hostState = snackbarHostState) },
            topBar = {
                Box(modifier = Modifier.clickable(
                    interactionSource = remember { MutableInteractionSource() },
                    indication = null
                ) { addComboClick('t') }) {
                    TopBar(
                        onClick = { backStack.removeLastOrNull() },
                        currentScreen = currentScreen,
                        supportUs = { backStack.add(Screen.Support) },
                        home = {
                            if (backStack.lastOrNull() != Screen.ProtectionActivated) {
                                backStack.add(Screen.ProtectionActivated)
                            }
                        }
                    )
                }
            },
            bottomBar = {
                Box(modifier = Modifier.clickable(
                    interactionSource = remember { MutableInteractionSource() },
                    indication = null
                ) { addComboClick('b') }) {
                    BottomBar(
                        modifier = Modifier,
                        appVersion = BuildConfig.VERSION_NAME,
                        androidVersion = Build.VERSION.RELEASE
                    ) {
                        if (isServiceRunning(context, MyAccessibilityService::class.java)) {
                            if (backStack.lastOrNull() != Screen.ProtectionActivated) {
                                backStack.add(Screen.ProtectionActivated)
                            }
                        }
                    }
                }
            },
            modifier = Modifier
                .background(MaterialTheme.colorScheme.surface)
                .windowInsetsPadding(WindowInsets.systemBars)
        ) { innerPadding ->
            val contentRepo : ContentRepo by inject(ContentRepo::class.java)
            NavDisplay(
                modifier = Modifier.padding(innerPadding),
                backStack = backStack,
                onBack = { backStack.removeLastOrNull() },
                entryDecorators = listOf(
                    rememberSceneSetupNavEntryDecorator(),
                    rememberSavedStateNavEntryDecorator()
                ),
                entryProvider = { key ->
                    when (key) {
                        Screen.ProtectionActivated -> NavEntry(key) {
                            ProtectionActivatedScreen(
                                onSupportClick = { backStack.add(Screen.Support) },
                                onBlockAppClick = { dialogState = DialogState.BlockApps() },
                                onReportClick = { dialogState = DialogState.ReportProblem },
                                onConfirmProtectionClick = { dialogState = DialogState.HowItWorks },
                                onAddKeyword = { viewModel.addBlockedWord(it) },
                                onRemoveKeyword = { viewModel.removeBlockedWord(it) },
                                keywords = viewModel.blockedWords.collectAsState().value.toSet(),
                                onUpdateClick = { updateStatus ->
                                    when (updateStatus) {
                                        UpdateState.Downloaded -> {
                                            context.installApk(viewModel.updateFile())
                                        }

                                        is UpdateState.Failed,
                                        UpdateState.NoUpdate,
                                            -> {
                                            viewModel.handleUpdateStatus()
                                        }

                                        else -> {
                                        }
                                    }

                                },
                                updateState = viewModel.updateState.value,
                            )
                        }

                        Screen.Support -> NavEntry(key) {
                            val isRunning = MyAccessibilityService.isRunning.collectAsState().value
                            SupportScreen(
                                onSupportClick = { openUrl(SUPPORT_URL) },
                                onJoinClick = { openUrl(JOIN_URL) },
                                onShareLogFile = { this@AppActivity.shareFile(viewModel.getLogFile()) },
                                onStopBlocking = {
                                    MyAccessibilityService.isRunning.value =
                                        !MyAccessibilityService.isRunning.value
                                },
                                onOpenScreenShotWindow = {
                                    viewModel.showScreenshotOverlay(true)

                                },
                                isBlocking = isRunning
                            )
                        }

                        Screen.EnableProtection -> NavEntry(key) {
                            var selectedLevel by remember { mutableStateOf(DnsProtectionLevel.LOW) }

                            EnableProtectionScreen(
                                report = { dialogState = DialogState.ReportProblem },
                                enableProtection = { level: DnsProtectionLevel ->
                                    selectedLevel = level
                                    when {

                                        !notificationPermission -> dialogState =
                                            DialogState.Permission(PermissionState.Notification)

                                        !overlayPermission -> dialogState =
                                            DialogState.Permission(PermissionState.Overlay)

                                        !accessibilityPermission -> dialogState =
                                            DialogState.Permission(PermissionState.Accessibility)

                                        else -> dialogState = DialogState.EnableProtectionConfirm(
                                            level = selectedLevel,
                                        )
                                    }
                                },
                                selectedLevel = selectedLevel,
                            )
                        }
                    }
                }
            )
        }
    }

    private fun refreshPermissionState() {
        if (!notificationPermission) {
            notificationPermission = hasNotificationPermission()
        }
        if (!overlayPermission) {
            overlayPermission = hasOverlayPermission()
        }
        if (!usageStatsPermission) {
            usageStatsPermission = hasUsageStatsPermission()
        }
        if (!accessibilityPermission) {
            accessibilityPermission = hasAccessibilityPermission()
        }
        permissionState = when {
            !notificationPermission -> PermissionState.Notification
            !overlayPermission -> PermissionState.Overlay
            !accessibilityPermission -> PermissionState.Accessibility
            else -> null
        }

    }




    override fun onResume() {
        super.onResume()
        refreshPermissionState()
    }


    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        refreshPermissionState()
    }


    private fun grantPermission(permissionState: PermissionState) {
        when (permissionState) {
            PermissionState.Notification -> {
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                    requestPermissions(arrayOf(POST_NOTIFICATIONS), 0)
                }
            }

            PermissionState.Overlay -> requestDrawOverlaysPermission()
            PermissionState.Accessibility -> requestAccessibilityPermission()
            PermissionState.Administrative -> requestAdminPermission(adminReceiver, requestAdmin)
            PermissionState.Granted -> {}
        }
    }

    companion object {
        const val TAG = "MainActivity"
    }

    override fun attachBaseContext(newBase: Context) {
        val context = LocaleHelper.forceArabicLocale(newBase)
        super.attachBaseContext(context)
    }
}

package com.mafazaa.ainaa.domain.repo
import com.mafazaa.ainaa.data.local.SharedPrefs import kotlinx.coroutines.GlobalScope import kotlinx.coroutines.launch import kotlinx.coroutines.flow.Flow
interface ContentRepo { val blockedWordsStatus: Flow<List<String>> fun getBlockedWords() fun removeKeyWord(word: String) fun addKeyWord(word: String) }

package com.mafazaa.ainaa.domain.repo
import com.mafazaa.ainaa.data.local.SharedPrefs import kotlinx.coroutines.GlobalScope import kotlinx.coroutines.launch import kotlinx.coroutines.flow.Flow import kotlinx.coroutines.flow.StateFlow
interface ContentRepo { val blockedWordsStatus: StateFlow<List<String>> fun getBlockedWords() fun removeKeyWord(word: String) fun addKeyWord(word: String) }

package com.mafazaa.ainaa.service

import android.accessibilityservice.AccessibilityService
import android.accessibilityservice.AccessibilityServiceInfo
import android.annotation.SuppressLint
import android.app.AlarmManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.util.Log
import android.view.accessibility.AccessibilityEvent
import com.mafazaa.ainaa.R
import com.mafazaa.ainaa.data.local.SharedPrefs
import com.mafazaa.ainaa.domain.models.BlockReason
import com.mafazaa.ainaa.domain.models.ScriptResult
import com.mafazaa.ainaa.domain.repo.ScriptRepo
import com.mafazaa.ainaa.helpers.DeviceUtils
import com.mafazaa.ainaa.helpers.LockOverlayManager
import com.mafazaa.ainaa.helpers.ScreenAnalyser
import com.mafazaa.ainaa.utils.MyLog
import com.mafazaa.ainaa.utils.MyLog.logUiTree
import com.mafazaa.ainaa.utils.block
import com.mafazaa.ainaa.utils.cancelRestartAlarm
import com.mafazaa.ainaa.utils.cancelWatchdog
import com.mafazaa.ainaa.utils.checkBlockedApp
import com.mafazaa.ainaa.utils.createNotification
import com.mafazaa.ainaa.utils.scheduleRestart
import com.mafazaa.ainaa.utils.scheduleWatchdog
import com.mafazaa.ainaa.utils.shareFile
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch
import org.koin.java.KoinJavaComponent.inject
import kotlin.time.measureTimedValue

@SuppressLint("AccessibilityPolicy")
class MyAccessibilityService : AccessibilityService() {
    val lockOverlayManager: LockOverlayManager by inject(LockOverlayManager::class.java)
    internal val serviceScope = CoroutineScope(Dispatchers.Default + Job())
    internal var alarmManager: AlarmManager? = null
    internal var watchdogPendingIntent: PendingIntent? = null
    internal val sharedPrefs: SharedPrefs by inject(SharedPrefs::class.java)
    private val scriptRepo: ScriptRepo by inject(ScriptRepo::class.java)

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        when (intent?.action) {
            ACTION_START_FOREGROUND -> {
                startForeground(
                    NOTIFICATION_ID,
                    createNotification()
                )
                MyLog.i(TAG, "Accessibility Service started in foreground.")
                startAccessibilityService()
            }
            ACTION_START -> {
                MyLog.i(TAG, "Accessibility Service started and moved to foreground.")
            }
            ACTION_STOP -> {
                stopForeground(STOP_FOREGROUND_REMOVE)
                stopSelf()

            }
            ACTION_SHARE_CURRENT_SCREEN -> {
                serviceScope.launch {
                    val screenAnalysis = ScreenAnalyser.analyzeScreen(
                        rootInActiveWindow, getString(R.string.app_name)
                    )
                    shareFile(logUiTree("screenShot", screenAnalysis))
                }
            }
            else -> {
                MyLog.w(TAG, "Unknown action received: ${intent?.action}")
            }
        }
        return START_STICKY
    }
    companion object {
        fun Context.startAccessibilityService(action: String = ACTION_START_FOREGROUND) {
            val intent = Intent(this, MyAccessibilityService::class.java).apply {
                this@apply.action = if (action == ACTION_START_FOREGROUND) {
                    ACTION_START_FOREGROUND
                } else {
                    ACTION_START
                }
            }
            startService(intent)
        }

        const val ACTION_STOP = "STOP_ACCESSIBILITY"
        const val ACTION_START = "START_ACCESSIBILITY"

        const val ACTION_START_FOREGROUND = "START_ACCESSIBILITY_FOREGROUND"
        const val ACTION_SHARE_CURRENT_SCREEN = "SHARE_CURRENT_SCREEN"
        internal const val NOTIFICATION_ID = 101 // Unique ID for the notification
        internal const val NOTIFICATION_CHANNEL_ID = "AINAA_PROTECTION_CHANNEL"
        internal const val WATCHDOG_INTERVAL_MS =  15 *60 * 1000L

        const val TAG = "MyAccessibilityService"

        private val SETTINGS_PACKAGE = DeviceUtils.settingsPackageName
        private val ACCESSIBILITY_SETTINGS = "${SETTINGS_PACKAGE}.accessibility.AccessibilitySettings"
    }

    override fun onCreate() {
        super.onCreate()
        MyLog.i(TAG, "Accessibility Service created.")
    }

    override fun onServiceConnected() {
        super.onServiceConnected()
        val info = AccessibilityServiceInfo()
        info.flags = info.flags or AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS
        info.eventTypes = AccessibilityEvent.TYPES_ALL_MASK
        info.feedbackType = AccessibilityServiceInfo.FEEDBACK_GENERIC
        serviceInfo = info
        MyLog.i(TAG, "Accessibility Service connected.")
    }

    override fun onAccessibilityEvent(event: AccessibilityEvent?) {
        // Return early if event is null or service is not running
        event ?: return
        // Only handle window content changed events
        if (event.eventType != AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED &&
            event.eventType != AccessibilityEvent.TYPE_WINDOW_CONTENT_CHANGED) {
            return
        }
        if (event.eventType == AccessibilityEvent.TYPE_WINDOW_STATE_CHANGED) {
            val componentName = event.className?.toString()
            if (event.packageName == SETTINGS_PACKAGE &&
                (componentName == ACCESSIBILITY_SETTINGS ||
                        componentName?.contains("accessibility", true) == true)) {

                block(BlockReason.UsingBlockedApp(SETTINGS_PACKAGE))
                return
            }
        }

        rootInActiveWindow?.let { rootNode ->
            serviceScope.launch {
                // Analyze the current screen and measure the time taken
                val (analysisResult, analysisDuration) = measureTimedValue {
                    ScreenAnalyser.analyzeScreen(rootNode, getString(R.string.app_name))
                }
                Log.d(
                    TAG,
                    "Screen analyzed in ${analysisDuration.inWholeMilliseconds}ms, nodes=${analysisResult.nodesCount}"
                )
                val currentPackage = analysisResult.pkg
                if (checkBlockedApp(currentPackage)) {
                    MyLog.i(TAG, "Blocked app in use: $currentPackage")
                    block(BlockReason.UsingBlockedApp(currentPackage ?: "unknown"))
                    return@launch
                }
                // Evaluate scripts and measure the time taken
                val (scriptResult, scriptEvalDuration) = measureTimedValue {
                    scriptRepo.evaluate(
                        analysisResult
                    )
                }
                Log.d(TAG, "Script evaluated in ${scriptEvalDuration.inWholeMilliseconds}ms")
                when (scriptResult) {
                    is ScriptResult.Error -> {
                        MyLog.e(TAG, "Script evaluation error: ${scriptResult.error}")
                    }

                    is ScriptResult.Success -> {
                        if (scriptResult.matched) {
                            MyLog.i(
                                TAG,
                                "Blocking due to script match: ${scriptResult.scriptName} on ${analysisResult.pkg}"
                            )
                            block(
                                BlockReason.TryingToDisable(
                                    scriptResult.scriptName,
                                    analysisResult
                                )
                            )
                            return@launch
                        }
                    }
                }
            }
        }
    }

    override fun onInterrupt() {
        serviceScope.cancel()
        MyLog.w(TAG, "Service interrupted")

    }

    override fun onTaskRemoved(rootIntent: Intent?) {
        MyLog.d(TAG, "Restart broadcast sent")
        super.onTaskRemoved(rootIntent)
    }

    override fun onDestroy() {
        super.onDestroy()
        serviceScope.cancel()

    }
}

package com.mafazaa.ainaa.service

import android.accessibilityservice.AccessibilityService
import android.accessibilityservice.AccessibilityServiceInfo
import android.annotation.SuppressLint
import android.app.AlarmManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.util.Log
